import json
import sys
import time
import urllib.error
import urllib.request
from datetime import datetime, timezone

BASE = "http://localhost:8080"
START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END = datetime(2025, 6, 1, tzinfo=timezone.utc)  # exclusive upper bound = 31 May inclusive


def request(method, path, token=None, max_attempts=20):
    attempt = 0
    while True:
        attempt += 1
        headers = {}
        if token:
            headers["Authorization"] = f"Bearer {token['value']}"
        req = urllib.request.Request(BASE + path, method=method, headers=headers)
        try:
            with urllib.request.urlopen(req, timeout=30) as resp:
                return resp.status, json.loads(resp.read().decode())
        except urllib.error.HTTPError as e:
            body = e.read().decode(errors="replace")
            if e.code == 401 and token is not None:
                # Token expired: fetch a new one and retry the same request.
                print(f"  401 on {path}, refreshing token", file=sys.stderr)
                token["value"] = get_token()
                continue
            if e.code == 429:
                wait = e.headers.get("Retry-After")
                wait_s = float(wait) if wait else 5.0
                print(f"  429 on {path}, Retry-After={wait}, sleeping {wait_s}s", file=sys.stderr)
                time.sleep(wait_s)
                continue
            if e.code == 404:
                return 404, body
            if e.code >= 500 and attempt < max_attempts:
                print(f"  {e.code} on {path}, retry {attempt}", file=sys.stderr)
                time.sleep(min(2 ** attempt, 30))
                continue
            raise RuntimeError(f"{method} {path} failed: {e.code} {body[:300]}")
        except (urllib.error.URLError, TimeoutError, ConnectionError) as e:
            if attempt < max_attempts:
                print(f"  network error on {path}: {e}, retry {attempt}", file=sys.stderr)
                time.sleep(min(2 ** attempt, 30))
                continue
            raise


def get_token():
    _, body = request("POST", "/token")
    return body["token"]


def round_half_up_div(num, den):
    # num and den are non-negative integers; returns num/den rounded half up.
    q, r = divmod(num, den)
    if 2 * r >= den:
        q += 1
    return q


def main():
    token = {"value": get_token()}

    # Walk every page by following "next", and check against total_pages.
    orders_raw = []
    pages_seen = []
    path = "/orders?page=1"
    total_pages = None
    while path:
        status, body = request("GET", path, token)
        assert status == 200, status
        pages_seen.append(body["page"])
        total_pages = body["total_pages"]
        orders_raw.extend(body["items"])
        path = body["next"]
        if path:
            print(f"page {body['page']}/{total_pages}: {len(body['items'])} items", file=sys.stderr)

    expected = list(range(1, total_pages + 1))
    if pages_seen != expected:
        raise SystemExit(f"page mismatch: got {pages_seen}, expected {expected}")

    # Deduplicate by order id, counting repeated listings.
    by_id = {}
    duplicates_skipped = 0
    conflicting_dupes = 0
    for o in orders_raw:
        oid = o["id"]
        if oid in by_id:
            duplicates_skipped += 1
            if by_id[oid] != o:
                conflicting_dupes += 1
        else:
            by_id[oid] = o

    statuses = {}
    for o in by_id.values():
        statuses[o["status"]] = statuses.get(o["status"], 0) + 1

    # Filter: exact "shipped", UTC date range.
    qualifying = []
    for o in by_id.values():
        if o["status"] != "shipped":
            continue
        t = datetime.fromisoformat(o["placed_at"]).astimezone(timezone.utc)
        if START <= t < END:
            qualifying.append(o)

    # Customer lookups, cached per id.
    customers = {}
    missing_customers = []
    for o in qualifying:
        cid = o["customer_id"]
        if cid in customers or cid in missing_customers:
            continue
        status, body = request("GET", f"/customers/{cid}", token)
        if status == 404:
            missing_customers.append(cid)
        else:
            customers[cid] = body

    by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
    total = 0
    unresolved = 0
    for o in qualifying:
        c = customers.get(o["customer_id"])
        if c is None:
            unresolved += 1
            continue
        pct = c["discount_pct"]
        # amount * (100 - pct) / 100, rounded half up per order, in integer cents.
        discounted = round_half_up_div(o["amount_cents"] * (100 - pct), 100)
        total += discounted
        by_region[c["region"]] += discounted

    result = {
        "total_cents": total,
        "order_count": len(qualifying),
        "duplicates_skipped": duplicates_skipped,
        "by_region": by_region,
    }

    print(json.dumps(result, indent=2))
    print(
        f"pages={len(pages_seen)} raw_items={len(orders_raw)} distinct={len(by_id)} "
        f"statuses={statuses} conflicting_dupes={conflicting_dupes} "
        f"missing_customers={missing_customers} unresolved={unresolved}",
        file=sys.stderr,
    )
    with open(sys.argv[1], "w") as f:
        json.dump(result, f, indent=2)
        f.write("\n")


if __name__ == "__main__":
    main()

